const raw = $json.output[0].content[0].text;
const limpio = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(limpio);

return [{
  json: {
    ...$json,
    decision: parsed.decision,
    confianza: parsed.confianza,
    motivo: parsed.motivo
  }
}];

const item = $input.item.json;
let estado = null, respuestaTexto = null, pedidoId = null, chatId = null;

if (item.callback_query) {
  const data = item.callback_query.data;
  const [accion, id] = data.split('_');
  pedidoId = id;
  chatId = item.callback_query.message.chat.id;
  estado = (accion === 'confirmar') ? 'Confirmó' : 'Modificar Dirección';
} else if (item.message) {
  respuestaTexto = item.message.text;
  chatId = item.message.chat.id;
  estado = 'Modificar Dirección';
}

return [{
  json: { estado, respuesta_texto: respuestaTexto, pedido_id: pedidoId, chat_id: chatId, origen: pedidoId ? 'boton' : 'texto' }
}];

