const errores = $('Traer Errores del Día').all();
const totalPedidos = $('Traer Pedidos del Día').all().length;
const tasaError = totalPedidos > 0 ? +(errores.length / totalPedidos * 100).toFixed(1) : 0;
const tasaReintentos = $('Calcular Tiempos y Reintentos').first().json.tasa_reintentos;
const tiempoReaccion = $('Calcular Tiempo de Reacción').first().json.tiempo_reaccion_promedio;
const tiempos = $('Calcular Tiempos y Reintentos').first().json.filas_tiempos;
const latenciaAlta = tiempos.some(t => t.tiempo_promedio > 2000);

let indice = 100 - (tasaError*2) - (tasaReintentos*1) - (tiempoReaccion>5?10:0) - (latenciaAlta?10:0);
indice = Math.max(0, Math.round(indice));
const estado = indice>=85 ? 'Óptimo' : indice>=60 ? 'Estable' : 'Crítico';

const porSistema = {};
errores.forEach(e => {
  const s = e.json['property_sistema_afectado'] || 'Desconocido';
  porSistema[s] = (porSistema[s]||0)+1;
});
const desglose = Object.entries(porSistema).map(([s,c])=>`${s} ${c}`).join(' · ');

return [{ json: {
  errores_hoy: errores.length,
  errores_desglose: desglose || 'Sin errores',
  tasa_error: tasaError,
  tasa_reintentos: tasaReintentos,
  tiempo_reaccion: tiempoReaccion,
  indice_salud: indice,
  estado_salud_sistema: estado,
} }];

const item = $input.item.json;
const campos = ['Teléfono', 'Dirección', 'Producto'];
const faltante = campos.find(c => !item[c] || String(item[c]).trim() === '');

return [{
  json: {
    ...item,
    datos_completos: !faltante,
    campo_faltante: faltante || null
  }
}];

const raw = $input.first().json.output[0].content[0].text;
const limpio = raw.replace(/```json|```/g, '').trim();
const kpi = JSON.parse(limpio);
return [{ json: kpi }];

const pedidos = $input.all().filter(p => p.json.property_fecha_primera_reacción);
const minutos = pedidos
  .map(p => {
    const ingreso = new Date(p.json.property_fecha_ingreso);
    const reaccion = new Date(p.json.property_fecha_primera_reacción);
    return (reaccion - ingreso) / 60000;
  })
  .filter(m => !isNaN(m) && isFinite(m));
const promedio = minutos.length ? +(minutos.reduce((a,b)=>a+b,0)/minutos.length).toFixed(1) : 0;
return [{ json: { tiempo_reaccion_promedio: promedio } }];

const CATEGORIA_POR_NODO = {
  'Actualizar Pedido (Confirmación Detectada)': 'Notion',
  'Actualizar Pedido Botón': 'Notion',
  'Actualizar Pedido Texto': 'Notion',
  'Buscar Pedido por Chat ID': 'Notion',
  'Buscar Pedido por Chat ID (Amplio)': 'Notion',
  'Buscar Pedido por ID': 'Notion',
  'Calcular KPI Negocio': 'OpenAI',
  'Cancelar Pedido': 'Telegram',
  'Clasificar Intención del Mensaje': 'OpenAI',
  'Confirmar Pedido': 'Telegram',
  'Consultar Historial Comprador': 'Notion',
  'Enviar Ack Modificar Dirección': 'Telegram',
  'Enviar Confirmación': 'Telegram',
  'Enviar Confirmación Inmediata (Botón)': 'Telegram',
  'Enviar Confirmación Inmediata (Texto)': 'Telegram',
  'Enviar Recordatorio (1/2)': 'Telegram',
  'Enviar Recordatorio (2/2)': 'Telegram',
  'Enviar Recordatorio Dirección (1/2)': 'Telegram',
  'Enviar Recordatorio Dirección (2/2)': 'Telegram',
  'Enviar Reporte por Correo': 'Gmail',
  'Evaluar Riesgo - Motor de Decisión': 'OpenAI',
  'Guardar Reporte en Dashboard': 'Notion',
  'Traer Datos Actuales HITL': 'Notion',
  'Marcar Revisión Humana Requerida': 'Notion',
  'HITL': 'Gmail',
  'Interpretar Corrección de Dirección': 'OpenAI',
  'Marcar Cancelación Enviada TimeOut': 'Notion',
  'Marcar Confirmación Enviada (Botón)': 'Notion',
  'Marcar Confirmación Enviada (Texto)': 'Notion',
  'Marcar Confirmación Enviada (Validación Dirección)': 'Notion',
  'Marcar Dirección Validada': 'Notion',
  'Marcar Recordatorio Enviado (1/2)': 'Notion',
  'Marcar Recordatorio Enviado (2/2)': 'Notion',
  'Notificar Cancelación (Mal Historial)': 'Telegram',
  'Notificar Mensaje Sin Pedido Asociado': 'Gmail',
  'Notificar falla Slack': 'Gmail',
  'Registrar Cancelación del Pedido': 'Notion',
  'Registrar Cancelación del Pedido (Mal Historial)': 'Notion',
  'Registrar Confirmación del Pedido': 'Notion',
  'Registrar Log': 'Notion',
  'Registrar Pedido Incompleto': 'Notion',
  'Revalidar Dirección Corregida': 'Google',
  'Traer Errores del Día': 'Notion',
  'Traer Estado Actualizado (1h)': 'Notion',
  'Traer Estado Actualizado C (24h)': 'Notion',
  'Traer Estado Actualizado C (7h)': 'Notion',
  'Traer Estado Actualizado D (24h)': 'Notion',
  'Traer Estado Actualizado D (7h)': 'Notion',
  'Traer Pedidos del Día': 'Notion',
  'Validar Dirección': 'Google',
  'Marcar Primera Reacción': 'Notion',
  'Guardar Tiempos por Integración': 'Notion',
};

const ejecuciones = $input.first().json.data || [];
const porIntegracion = {};
let totalNodos = 0, conReintento = 0;

for (const ej of ejecuciones) {
  const runData = (ej.data && ej.data.resultData && ej.data.resultData.runData) || {};
  for (const [nombreNodo, corridas] of Object.entries(runData)) {
    const cat = CATEGORIA_POR_NODO[nombreNodo];
    if (!cat) continue;
    totalNodos++;
    if (corridas.length > 1) conReintento++;
    const tiempoMs = corridas[corridas.length - 1].executionTime || 0;
    if (!porIntegracion[cat]) porIntegracion[cat] = [];
    porIntegracion[cat].push(tiempoMs);
  }
}

const filasTiempos = Object.entries(porIntegracion).map(([integracion, tiempos]) => ({
  json: { integracion, tiempo_promedio: Math.round(tiempos.reduce((a,b)=>a+b,0) / tiempos.length) }
}));

const tasaReintentos = totalNodos > 0 ? +(conReintento / totalNodos * 100).toFixed(1) : 0;
return [{ json: { filas_tiempos: filasTiempos, tasa_reintentos: tasaReintentos } }];

const componentes = $json.result?.address?.addressComponents || [];
const niveles = componentes.map(c => c.confirmationLevel);

let calidad;
if (niveles.includes('UNCONFIRMED_AND_SUSPICIOUS')) {
  calidad = 'No Valida';
} else if (niveles.includes('UNCONFIRMED_BUT_PLAUSIBLE')) {
  calidad = 'Revisar';
} else {
  calidad = 'Valida';
}

return [{ json: { ...$json, calidad_direccion: calidad } }];

